import numpy as np
from rk4 import rk4


def oscillatore(t, y):
    return [y[1], -y[0]]


def test_forma():
    t, Y = rk4(oscillatore, 0, [1, 0], 0.1, 10)
    assert t.shape == (11,) and Y.shape == (11, 2)


def test_ordine_quattro():
    errori = []
    for n in (50, 100):
        t, Y = rk4(oscillatore, 0, [1, 0], 2 * np.pi / n, n)
        errori.append(np.linalg.norm(Y[-1] - [1, 0]))   # dopo un periodo si torna al punto di partenza
    assert 12 < errori[0] / errori[1] < 20      # dimezzando h l'errore cala di ~16 volte
